1	import { useRouter } from "next/navigation";
2	import { useState, type FormEvent } from "react";
3	
4	export function SearchForm() {
5	  const router = useRouter();
6	  const [q, setQ] = useState("");
7	  const [open, setOpen] = useState(false);
8	
9	  function submit(e: FormEvent) {
10	    e.preventDefault();
11	    if (q.trim()) router.push(`/search?q=${encodeURIComponent(q.trim())}`);
12	  }
13	
14	  return (
15	    <form onSubmit={submit} role="search" className="relative">
16	      <input
17	        value={q}
18	        onChange={(e) => {
19	          setQ(e.target.value);
20	          setOpen(true);
21	        }}
22	        onFocus={() => setOpen(true)}
23	        onBlur={() => setTimeout(() => setOpen(false), 150)}
