"use client";

import type { Meeting, Summary } from "@/lib/model";
import type { usePlayer } from "@/lib/player";
import { MEETING_TEMPLATES } from "@/lib/templates";
import { fmtDate } from "@/lib/time";
import { useState } from "react";
import { ShareModal } from "./ShareModal";
import { ClipsPanel } from "./ClipsPanel";
import { DispatchModal } from "./DispatchModal";

type TabId = "summary" | "actions" | "clips" | "moments" | "email";

export function LeftPanel({
  meeting,
  player,
}: {
  meeting: Meeting;
  player: ReturnType<typeof usePlayer>;
}) {
  const tabOrder: { id: TabId; label: string; count?: number }[] = [
    { id: "summary", label: "Summary" },
    { id: "actions", label: "Action items", count: meeting.actionItems.length },
    { id: "clips", label: "Clips", count: meeting.highlights.length },
    { id: "moments", label: "Moments", count: meeting.highlights.length },
    { id: "email", label: "Follow-up" },
  ];
  const [tab, setTab] = useState<TabId>("summary");

  return (
    <div>
      <div className="mb-1 flex flex-wrap items-center gap-1" role="tablist" aria-label="Meeting artifacts">
        {tabOrder.map((tb) => (
          <button
            key={tb.id}
            role="tab"
            aria-selected={tab === tb.id}
            onClick={() => setTab(tb.id)}
            className={
              "rounded-full px-3 py-1.5 text-[13px] font-medium transition-colors " +
              (tab === tb.id
                ? "bg-ink text-paper"
                : "text-ink-soft hover:bg-line-soft hover:text-ink")
            }
          >
            {tb.label}
            {tb.count !== undefined && (
              <span className={"ml-1.5 font-mono text-[11px] " + (tab === tb.id ? "text-paper/70" : "text-ink-faint")}>
                {tb.count}
              </span>
            )}
          </button>
        ))}
      </div>

      <div className="pane p-5" role="tabpanel" aria-label={tab}>
        {tab === "summary" && <SummaryPanel meeting={meeting} player={player} />}
        {tab === "actions" && <ActionItems meeting={meeting} player={player} />}
        {tab === "clips" && <ClipsPanel meeting={meeting} />}
        {tab === "moments" && <HighlightsPanel meeting={meeting} player={player} />}
        {tab === "email" && <EmailPanel meeting={meeting} />}
      </div>
    </div>
  );
}

// ── Summary ──────────────────────────────────────────────────────────────────
function SummaryPanel({ meeting, player }: { meeting: Meeting; player: ReturnType<typeof usePlayer> }) {
  const templates = MEETING_TEMPLATES.filter((t) => meeting.summaries[t.id]);
  const [template, setTemplate] = useState(meeting.defaultTemplate);
  const summary: Summary = meeting.summaries[template] ?? meeting.summaries[meeting.defaultTemplate];

  return (
    <div>
      <div className="mb-3 flex items-center justify-between gap-3">
        <p className="text-[13px] text-ink-faint">
          {fmtDate(meeting.startedAt)} · drafted by Minutes, every line cites the moment
        </p>
        {/* template switcher — per-call summary style */}
        <label className="relative z-10 flex items-center gap-1.5 text-[12px] text-ink-soft">
          <span className="hidden sm:inline">Summary type</span>
          <select
            value={summary.template}
            onChange={(e) => setTemplate(e.target.value)}
            className="rounded-md border border-line bg-paper px-2 py-1 text-[12.5px] font-medium text-ink focus:outline-none"
          >
            {templates.map((t) => (
              <option key={t.id} value={t.id}>
                {t.name}
              </option>
            ))}
          </select>
        </label>
      </div>

      <p className="mb-5 font-[family-name:var(--font-display)] text-[17px] leading-relaxed tracking-tight">
        {summary.gist}
      </p>

      <div className="space-y-5">
        {summary.sections.map((sec) => (
          <div key={sec.heading}>
            <h3 className="eyebrow mb-2">{sec.heading}</h3>
            <ul className="space-y-2">
              {sec.bullets.map((b, i) => (
                <li key={i} className="flex gap-2.5 text-[14.5px] leading-relaxed">
                  <button
                    onClick={() => player.seek(b.cite)}
                    className="mt-[3px] shrink-0 rounded bg-record-soft px-1.5 py-px font-mono text-[11px] font-medium text-record tabular-nums hover:bg-record hover:text-paper"
                    title="Jump to this moment"
                    aria-label={`Jump to ${Math.floor(b.cite / 60)}:${String(Math.floor(b.cite % 60)).padStart(2, "0")}`}
                  >
                    {String(Math.floor(b.cite / 60)).padStart(2, "0")}:{String(Math.floor(b.cite % 60)).padStart(2, "0")}
                  </button>
                  <span>{b.text}</span>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Action items ─────────────────────────────────────────────────────────────
function ActionItems({ meeting, player }: { meeting: Meeting; player: ReturnType<typeof usePlayer> }) {
  const [done, setDone] = useState<Record<string, boolean>>({});
  const [dispatching, setDispatching] = useState<string | null>(null);
  const [toast, setToast] = useState<string | null>(null);

  function approveDispatch(a: (typeof meeting.actionItems)[number]) {
    setDispatching(null);
    setToast(`Dispatched to ${a.ownerName} — Minutes will nudge if the due date slips.`);
    setTimeout(() => setToast(null), 4200);
  }

  function byOwner() {
    const map = new Map<string, typeof meeting.actionItems>();
    for (const a of meeting.actionItems) {
      if (!map.has(a.ownerName)) map.set(a.ownerName, []);
      map.get(a.ownerName)!.push(a);
    }
    return map;
  }

  const speakers = meeting.speakers;

  return (
    <div>
      <p className="mb-4 text-[13px] text-ink-faint">
        Extracted with the owner and the moment they were committed — grouped by person.
      </p>
      <div className="space-y-5">
        {[...byOwner().entries()].map(([owner, items]) => {
          const sp = speakers.find((s) => s.name === owner);
          return (
            <div key={owner}>
              <h3 className="mb-2 flex items-center gap-2 text-[13.5px] font-semibold">
                <span
                  className="inline-block size-2.5 rounded-full"
                  style={{ background: sp?.color ?? "#8e9095" }}
                  aria-hidden
                />
                {owner}
              </h3>
              <ul className="space-y-2">
                {items.map((a) => (
                  <li
                    key={a.id}
                    className="flex items-start gap-2.5 rounded-lg border border-line-soft bg-paper px-3 py-2.5"
                  >
                    <input
                      type="checkbox"
                      checked={!!done[a.id]}
                      onChange={() => setDone((d) => ({ ...d, [a.id]: !d[a.id] }))}
                      className="mt-0.5 size-4 accent-[var(--ok)]"
                      aria-label={`Mark done: ${a.text}`}
                    />
                    <div className="min-w-0 flex-1">
                      <p className={"text-[14px] leading-snug " + (done[a.id] ? "text-ink-faint line-through" : "")}>
                        {a.text}
                      </p>
                      <p className="mt-1 flex items-center gap-2 text-[12px] text-ink-faint">
                        <span className="flex items-center gap-1">
                          <span aria-hidden className="text-[10px]">⏎</span>
                          due {a.due ? fmtDate(a.due) : "—"}
                        </span>
                        <button
                          onClick={() => player.seek(a.cite)}
                          className="rounded bg-record-soft px-1.5 py-px font-mono text-[10.5px] font-medium text-record tabular-nums hover:bg-record hover:text-paper"
                          aria-label="Jump to the moment this was said"
                        >
                          {String(Math.floor(a.cite / 60)).padStart(2, "0")}:{String(Math.floor(a.cite % 60)).padStart(2, "0")}
                        </button>
                      </p>
                    </div>
                    <button
                      onClick={() => setDispatching(a.id)}
                      className="mt-0.5 shrink-0 rounded-full border border-line bg-raised px-2.5 py-1 text-[11.5px] font-medium text-ink-soft hover:border-record hover:text-record"
                      aria-label={`Dispatch: ${a.text}`}
                    >
                      Dispatch ⚡
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          );
        })}
      </div>
      {dispatching && (
        <DispatchModal
          meeting={meeting}
          action={meeting.actionItems.find((a) => a.id === dispatching)!}
          onClose={() => setDispatching(null)}
          onApproved={() =>
            approveDispatch(meeting.actionItems.find((a) => a.id === dispatching)!)
          }
        />
      )}
      {toast && (
        <div
          role="status"
          className="fixed bottom-5 left-1/2 z-50 -translate-x-1/2 rounded-full bg-ink px-5 py-2.5 text-[13.5px] font-medium text-paper shadow-lg"
        >
          ⚡ {toast}
        </div>
      )}
    </div>
  );
}

// ── Highlights / Moments ─────────────────────────────────────────────────────
function HighlightsPanel({ meeting, player }: { meeting: Meeting; player: ReturnType<typeof usePlayer> }) {
  const [share, setShare] = useState<string | null>(null);

  if (meeting.highlights.length === 0)
    return (
      <p className="text-sm text-ink-faint">
        No moments were flagged during this call. Highlight anything during capture — or from the transcript afterwards — and it lands here as a shareable clip.
      </p>
    );

  const tagColor: Record<string, string> = {
    decision: "bg-ok-soft text-ok",
    risk: "bg-record-soft text-record",
    question: "bg-line-soft text-ink-soft",
    action: "bg-line-soft text-ink-soft",
    moment: "bg-line-soft text-ink-soft",
  };

  return (
    <div>
      <p className="mb-4 text-[13px] text-ink-faint">
        Flagged during the call. Each one is a clip you can hand to someone who wasn&rsquo;t there.
      </p>
      <ul className="space-y-3">
        {meeting.highlights.map((h) => (
          <li key={h.id} className="rounded-lg border border-line-soft bg-paper p-3.5">
            <div className="mb-1 flex items-center gap-2">
              <button
                onClick={() => player.seek(h.at)}
                className="rounded bg-record-soft px-1.5 py-px font-mono text-[11px] font-medium text-record tabular-nums hover:bg-record hover:text-paper"
              >
                {String(Math.floor(h.at / 60)).padStart(2, "0")}:{String(Math.floor(h.at % 60)).padStart(2, "0")}
              </button>
              {h.tag && (
                <span className={"rounded px-1.5 py-px text-[10px] font-semibold uppercase tracking-wide " + (tagColor[h.tag] ?? "bg-line-soft text-ink-soft")}>
                  {h.tag}
                </span>
              )}
              <button
                onClick={() => setShare(h.id)}
                className="ml-auto rounded-full border border-line bg-raised px-2.5 py-1 text-[12px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink"
              >
                Share clip
              </button>
            </div>
            <p className="text-[14.5px] font-medium leading-snug">{h.title}</p>
            {h.note && <p className="mt-1 text-[13px] leading-relaxed text-ink-soft">{h.note}</p>}
          </li>
        ))}
      </ul>
      {share && (
        <ShareModal
          meeting={meeting}
          highlightId={share}
          onClose={() => setShare(null)}
        />
      )}
    </div>
  );
}

// ── Follow-up email ──────────────────────────────────────────────────────────
function EmailPanel({ meeting }: { meeting: Meeting }) {
  const [copied, setCopied] = useState(false);
  async function copy() {
    try {
      await navigator.clipboard.writeText(meeting.emailDraft);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      setCopied(false);
    }
  }
  return (
    <div>
      <div className="mb-3 flex items-center justify-between">
        <p className="text-[13px] text-ink-faint">Drafted the moment the call ended — paste-ready.</p>
        <button
          onClick={copy}
          className="rounded-full border border-line bg-raised px-3 py-1.5 text-[13px] font-medium hover:border-ink-soft"
        >
          {copied ? "Copied" : "Copy email"}
        </button>
      </div>
      <pre className="scrollpane max-h-80 overflow-y-auto whitespace-pre-wrap rounded-lg border border-line-soft bg-paper p-4 font-[family-name:var(--font-ui)] text-[13.5px] leading-relaxed text-ink-soft">
        {meeting.emailDraft}
      </pre>
    </div>
  );
}

"use client";

import type { ActionItem, Meeting } from "@/lib/model";
import { useEffect, useState } from "react";
import { fmtDate, mmss } from "@/lib/time";

type Format = "email" | "jira";

/**
 * Agentic dispatch: the AI drafts the follow-up (mocked locally, honestly
 * labeled as a draft only you can approve) for one action item — an email or
 * a Jira ticket — and nothing leaves without Approve.
 */
export function DispatchModal({
  meeting,
  action,
  onClose,
  onApproved,
}: {
  meeting: Meeting;
  action: ActionItem;
  onClose: () => void;
  onApproved: () => void;
}) {
  const [phase, setPhase] = useState<"drafting" | "draft" | "approved">("drafting");
  const [format, setFormat] = useState<Format>("email");

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  // mock drafting latency
  useEffect(() => {
    const t = setTimeout(() => setPhase("draft"), 1400);
    return () => clearTimeout(t);
  }, [action.id]);

  const quote = meeting.transcript.find((u) => u.t <= action.cite && action.cite < u.t + u.dur + 4);
  const ownerFirst = action.ownerName.split(" ")[0];

  const email = [
    `Subject: ${ownerFirst} — follow through on "${shorten(action.text, 48)}"`,
    "",
    `Hi ${ownerFirst},`,
    "",
    `From today's ${meeting.title} (${fmtDate(meeting.startedAt)}) — this one is on you, due ${
      action.due ? fmtDate(action.due) : "this week"
    }:`,
    "",
    `  ${action.text}`,
    "",
    quote ? `Where it was agreed, verbatim:\n\n  “${quote.text}” [${mmss(quote.t)}]` : "",
    "",
    "If the date doesn't hold, reply with the one that does and I'll move the tracker.",
    "",
    "— drafted by Minutes, sending on your approval",
  ]
    .join("\n")
    .replace(/\n{3,}/g, "\n\n");

  const jira = [
    `Summary:  [${ownerFirst.toUpperCase()}] ${shorten(action.text, 64)}`,
    `Type:     Task · Priority: ${action.due && action.due <= "2026-10-31" ? "High" : "Medium"}`,
    `Due:      ${action.due ? fmtDate(action.due) : "—"}   Reported by: Minutes`,
    `Source:   ${meeting.title} @ [${mmss(action.cite)}] (linked recording moment)`,
    "",
    "Description:",
    `  Owner committed on the call. Quote as said:`,
    quote ? `  “${quote.text}” [${mmss(quote.t)}]` : `  ${action.text}`,
    "",
    `  Acceptance: the item is done and confirmed in next week's check-in,`,
    `  else the due date moves with a note.`,
  ].join("\n");

  const draft = format === "email" ? email : jira;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-ink/45 p-4"
      role="dialog"
      aria-modal="true"
      aria-label="Dispatch action item"
      onClick={onClose}
    >
      <div
        className="w-full max-w-lg rounded-xl border border-line bg-raised p-5 shadow-xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-start justify-between gap-3">
          <div>
            <p className="eyebrow mb-1">Dispatch this action item</p>
            <h2 className="font-[family-name:var(--font-display)] text-xl font-medium leading-snug tracking-tight">
              {action.text}
            </h2>
            <p className="mt-1 text-[12.5px] text-ink-faint">
              {action.ownerName} · {action.due ? `due ${fmtDate(action.due)}` : "no due date"} ·{" "}
              {meeting.title}
            </p>
          </div>
          <button onClick={onClose} className="shrink-0 text-[13px] text-ink-soft hover:text-ink">
            Close
          </button>
        </div>

        {phase === "drafting" && (
          <div className="mt-5 space-y-2" aria-busy="true" aria-label="AI is drafting">
            <p className="text-[13px] text-ink-faint">
              Drafting the {format === "email" ? "email" : "ticket"} from what was actually said…
            </p>
            {[92, 78, 88, 40].map((w, i) => (
              <div
                key={i}
                className="h-3.5 animate-pulse rounded bg-line-soft"
                style={{ width: `${w}%`, animationDelay: `${i * 120}ms` }}
              />
            ))}
          </div>
        )}

        {phase !== "drafting" && (
          <>
            <div className="mt-4 flex items-center gap-1" role="tablist" aria-label="Draft format">
              {(["email", "jira"] as Format[]).map((f) => (
                <button
                  key={f}
                  role="tab"
                  aria-selected={format === f}
                  onClick={() => setFormat(f)}
                  className={
                    "rounded-full px-3 py-1 text-[12.5px] font-medium " +
                    (format === f ? "bg-ink text-paper" : "text-ink-soft hover:bg-line-soft")
                  }
                >
                  {f === "email" ? "Email" : "Jira ticket"}
                </button>
              ))}
              <button
                onClick={() => navigator.clipboard?.writeText(draft)}
                className="ml-auto text-[12.5px] text-record underline underline-offset-2"
              >
                Copy draft
              </button>
            </div>
            <pre className="mt-2 max-h-72 overflow-y-auto whitespace-pre-wrap rounded-lg border border-line-soft bg-paper px-4 py-3 font-mono text-[12.5px] leading-relaxed text-ink-soft">
              {draft}
            </pre>
            {phase === "draft" ? (
              <div className="mt-4 flex items-center justify-between gap-3">
                <p className="text-[12px] text-ink-faint">
                  Mocked AI — nothing sends in this build, approval is honored in spirit.
                </p>
                <button
                  onClick={() => {
                    setPhase("approved");
                    setTimeout(onApproved, 500);
                  }}
                  className="shrink-0 rounded-full bg-ink px-4.5 py-2 text-[13.5px] font-medium text-paper hover:opacity-90"
                >
                  Approve &amp; send
                </button>
              </div>
            ) : (
              <p className="mt-4 text-[13.5px] font-medium text-ok">
                ✓ Approved — dispatched to {action.ownerName}.
              </p>
            )}
          </>
        )}
      </div>
    </div>
  );
}

function shorten(s: string, n: number): string {
  return s.length <= n ? s : s.slice(0, n - 1) + "…";
}

"use client";

import type { Highlight, Meeting, Utterance } from "@/lib/model";
import { mmss, hms } from "@/lib/time";
import { useEffect, useRef, useState } from "react";

const CLIP_SECONDS = 28;

/** The AI clip list: each highlight becomes a ready-to-share vertical clip. */
export function ClipsPanel({ meeting }: { meeting: Meeting }) {
  const [openId, setOpenId] = useState<string | null>(null);

  const clips = meeting.highlights.map((h) => ({
    h,
    speaker: dominantSpeaker(meeting, h.at, CLIP_SECONDS),
    lines: clipLines(meeting, h.at, CLIP_SECONDS),
  }));

  const open = clips.find((c) => c.h.id === openId);

  return (
    <div>
      <p className="mb-3 text-[12.5px] text-ink-faint">
        Minutes cut this call into vertical clips for social — captions on, speaker on, nothing
        to edit.
      </p>
      <ul className="space-y-2.5">
        {clips.map((c) => (
          <ClipRow key={c.h.id} clip={c} onOpen={() => setOpenId(c.h.id)} />
        ))}
      </ul>
      {open && <ClipTheatre clip={open} meeting={meeting} onClose={() => setOpenId(null)} />}
    </div>
  );
}

type Clip = {
  h: Highlight;
  speaker: { id: string; name: string; color: string } | undefined;
  lines: Utterance[];
};

function ClipRow({ clip, onOpen }: { clip: Clip; onOpen: () => void }) {
  const { h, speaker } = clip;
  return (
    <li>
      <button
        onClick={onOpen}
        className="flex w-full items-center gap-3 rounded-lg border border-line-soft bg-raised px-3 py-2.5 text-left hover:border-ink-soft"
        aria-label={`Play clip: ${h.title}`}
      >
        {/* mini vertical thumb */}
        <span
          className="grid w-9 shrink-0 place-items-center rounded text-[10px] font-semibold text-paper"
          style={{ aspectRatio: "9/16", background: speaker?.color ?? "#374151" }}
          aria-hidden
        >
          9:16
        </span>
        <span className="min-w-0">
          <span className="block truncate text-[14px] font-medium">{h.title}</span>
          <span className="mt-0.5 block text-[12px] text-ink-faint">
            {h.tag ?? "clip"} · starts {mmss(h.at)} · {CLIP_SECONDS}s · {speaker?.name}
          </span>
        </span>
        <span className="ml-auto shrink-0 rounded-full bg-ink px-3 py-1 text-[12px] font-medium text-paper">
          Play
        </span>
      </button>
    </li>
  );
}

/** Full-screen-ish theatre: the 9:16 player with TikTok-style captions. */
function ClipTheatre({
  clip,
  meeting,
  onClose,
}: {
  clip: Clip;
  meeting: Meeting;
  onClose: () => void;
}) {
  const [t, setT] = useState(0); // clip-local seconds
  const [playing, setPlaying] = useState(true);
  const raf = useRef<number | null>(null);

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  useEffect(() => {
    if (!playing) return;
    let last = performance.now();
    const step = (now: number) => {
      setT((v) => {
        const nv = v + (now - last) / 1000;
        last = now;
        return nv >= CLIP_SECONDS ? CLIP_SECONDS : nv;
      });
      raf.current = requestAnimationFrame(step);
    };
    raf.current = requestAnimationFrame(step);
    return () => {
      if (raf.current) cancelAnimationFrame(raf.current);
    };
  }, [playing]);

  const { h, speaker } = clip;
  const activeIdx = clip.lines.findIndex((u) => t + h.at >= u.t && t + h.at < u.t + u.dur);
  const finished = t >= CLIP_SECONDS;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-ink/85 p-4"
      role="dialog"
      aria-modal="true"
      aria-label={`Clip: ${h.title}`}
      onClick={onClose}
    >
      <div className="flex max-h-full items-end gap-4" onClick={(e) => e.stopPropagation()}>
        {/* the vertical video */}
        <div
          className="relative flex w-[270px] shrink-0 flex-col overflow-hidden rounded-2xl bg-ink text-paper shadow-2xl"
          style={{ aspectRatio: "9/16", maxHeight: "78vh" }}
        >
          {/* speaker color wash */}
          <div
            className="pointer-events-none absolute inset-x-0 top-0 h-1/3 opacity-25"
            style={{
              background: `linear-gradient(to bottom, ${speaker?.color ?? "#374151"}, transparent)`,
            }}
            aria-hidden
          />
          <div className="relative flex items-center justify-between px-3 pt-3">
            <span className="flex items-center gap-1.5 text-[12px] font-semibold">
              <span
                className="inline-block size-2 rounded-full"
                style={{ background: speaker?.color ?? "#888" }}
                aria-hidden
              />
              {speaker?.name ?? "Unknown"}
            </span>
            <span className="rounded-full bg-paper/15 px-1.5 py-px font-mono text-[9.5px]">
              {mmss(h.at)}
            </span>
          </div>
          <div className="relative flex-1" aria-hidden />
          {/* captions rising from the bottom */}
          <div className="relative flex h-[38%] flex-col justify-end overflow-hidden px-3 pb-4">
            {(activeIdx < 0 ? clip.lines.slice(0, 2) : clip.lines.slice(Math.max(0, activeIdx - 1), activeIdx + 2)).map(
              (u, i, arr) => {
                const globalIdx = activeIdx < 0 ? i : i + Math.max(0, activeIdx - 1);
                return (
                  <p
                    key={globalIdx}
                    className={
                      "text-[13px] leading-snug transition-opacity duration-300 " +
                      (globalIdx === activeIdx
                        ? "font-semibold text-paper"
                        : i < arr.length - 1 && globalIdx < activeIdx
                          ? "text-paper/40"
                          : "text-paper/70")
                    }
                  >
                    {u.text}
                  </p>
                );
              }
            )}
          </div>
          {/* progress */}
          <div className="relative px-3 pb-3">
            <div className="h-1 overflow-hidden rounded-full bg-paper/20">
              <div
                className="h-full rounded-full bg-record"
                style={{ width: `${(t / CLIP_SECONDS) * 100}%` }}
              />
            </div>
          </div>
          {/* play / replay */}
          <button
            onClick={() => {
              if (finished) {
                setT(0);
                setPlaying(true);
              } else setPlaying((p) => !p);
            }}
            className="absolute inset-0 grid place-items-center"
            aria-label={finished ? "Replay clip" : playing ? "Pause clip" : "Play clip"}
          >
            {(finished || !playing) && (
              <span className="grid size-14 place-items-center rounded-full bg-ink/60 text-xl backdrop-blur">
                {finished ? "↻" : "▶"}
              </span>
            )}
          </button>
        </div>

        {/* side meta */}
        <div className="max-w-xs pb-1 text-paper">
          <p className="text-[11.5px] font-medium uppercase tracking-wide text-paper/60">
            Smart clip · {meeting.title.split("—")[0].trim()}
          </p>
          <h2 className="mt-1.5 font-[family-name:var(--font-display)] text-2xl font-medium leading-tight">
            {h.title}
          </h2>
          {h.note && <p className="mt-2 text-[13px] leading-relaxed text-paper/70">{h.note}</p>}
          <p className="mt-3 font-mono text-[11.5px] text-paper/50 tabular-nums">
            {mmss(h.at)}–{mmss(Math.min(meeting.duration, h.at + CLIP_SECONDS))} of{" "}
            {hms(meeting.duration)}
          </p>
          <div className="mt-5 flex flex-col items-start gap-2">
            <a
              href={`/share/${meeting.id}?h=${h.id}`}
              target="_blank"
              rel="noreferrer"
              className="rounded-full bg-paper/15 px-3.5 py-2 text-[13px] font-medium hover:bg-paper/25"
            >
              Share this clip ↗
            </a>
            <a
              href={`/m/${meeting.id}?t=${h.at}`}
              className="text-[13px] text-paper/60 underline underline-offset-2 hover:text-paper"
            >
              Keep the whole call instead
            </a>
            <button
              onClick={onClose}
              className="mt-3 text-[13px] text-paper/60 hover:text-paper"
            >
              Close (esc)
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ── helpers ────────────────────────────────────────────────────────────────── */

function clipLines(meeting: Meeting, at: number, len: number) {
  return meeting.transcript.filter((u) => u.t + u.dur > at - 1 && u.t < at + len);
}

function dominantSpeaker(meeting: Meeting, at: number, len: number) {
  const tally = new Map<string, number>();
  for (const u of clipLines(meeting, at, len))
    tally.set(u.speaker, (tally.get(u.speaker) ?? 0) + u.dur);
  let best: { id: string; n: number } | null = null;
  for (const [id, n] of tally) {
    if (id === meeting.speakers.find((s) => s.self)?.id && tally.size > 1) continue;
    if (!best || n > best.n) best = { id, n };
  }
  return meeting.speakers.find((s) => s.id === (best?.id ?? tally.keys().next().value));
}

"use client";

import type { Meeting } from "@/lib/model";
import type { usePlayer } from "@/lib/player";
import { useEffect, useRef, useState } from "react";
import { mmss } from "@/lib/time";

/* ── answer synthesis ─────────────────────────────────────────────────────────
 * This build mocks the AI: answers are retrieved from the transcript, then
 * streamed token-by-token like a real model. Text and citation tokens
 * alternate, so citations land inline exactly where a model puts [04:23].
 * -------------------------------------------------------------------------- */

type Cite = { t: number };
type Token = { text: string } | { cite: Cite };

const STOP = new Set([
  "what","was","the","did","who","how","why","is","are","we","our","a","an","to","for","said",
  "about","think","when","of","on","in","with","that","this","they","their","have","has","and",
]);

function termsOf(q: string): string[] {
  return q
    .toLowerCase()
    .replace(/[^a-z0-9% ]/g, "")
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOP.has(w));
}

function composeAnswer(meeting: Meeting, query: string, spName: (id: string) => string): Token[] {
  const terms = termsOf(query);
  if (terms.length === 0) {
    return [
      {
        text:
          "I need a few real words to search this call — try phrasing it the way someone said it, like a product name or a decision. Everything I answer is made of quotes you can play.",
      },
    ];
  }

  const scored = meeting.transcript
    .map((u) => ({
      u,
      score: terms.reduce((n, term) => n + (u.text.toLowerCase().includes(term) ? 1 : 0), 0),
    }))
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score || a.u.t - b.u.t);

  // action items that share terms get woven in
  const actions = meeting.actionItems.filter((a) =>
    terms.some(
      (term) => a.text.toLowerCase().includes(term) || a.ownerName.toLowerCase().includes(term)
    )
  );

  const summary = meeting.summaries[meeting.defaultTemplate];
  const bullets = (summary?.sections ?? [])
    .flatMap((s) => s.bullets)
    .filter((b) => terms.some((term) => b.text.toLowerCase().includes(term)))
    .slice(0, 1);

  const top = scored.slice(0, Math.min(3, scored.length));
  const tokens: Token[] = [];

  if (bullets.length > 0) {
    tokens.push({ text: bullets[0].text + " " });
    tokens.push({ cite: { t: bullets[0].cite } });
    if (top.length > 0) tokens.push({ text: "\n\nAnd in the caller's words:\n" });
  }

  if (top.length === 0) {
    tokens.push({
      text:
        "I couldn't find that in this call. Try words someone actually said, or use cross-meeting Search to look through every meeting at once.",
    });
    return tokens;
  }

  if (top.length === 1) {
    tokens.push({ text: `${spName(top[0].u.speaker)} said it directly:\n\n“${top[0].u.text}” ` });
    tokens.push({ cite: { t: top[0].u.t } });
  } else {
    if (bullets.length === 0) tokens.push({ text: "What was said, in the order it came up:\n" });
    top.forEach((s, j) => {
      tokens.push({ text: `${j > 0 ? "\n" : ""}· ${spName(s.u.speaker)}: “${s.u.text}” ` });
      tokens.push({ cite: { t: s.u.t } });
    });
  }

  if (actions.length > 0) {
    const a = actions[0];
    tokens.push({
      text: `\nThat turned into an action item: ${a.ownerName} — ${a.text}${a.due ? ` (due ${a.due})` : ""} `,
    });
    tokens.push({ cite: { t: a.cite } });
  }
  return tokens;
}

/* ── chat panel ─────────────────────────────────────────────────────────────── */

type Turn = {
  q: string;
  tokens: Token[];
  /** characters of the flattened token stream revealed so far */
  revealed: number;
  total: number;
};

function tokenChars(tk: Token): number {
  return "cite" in tk ? 6 : tk.text.length;
}

export function ChatPanel({
  meeting,
  player,
  className,
}: {
  meeting: Meeting;
  player: ReturnType<typeof usePlayer>;
  className?: string;
}) {
  const [q, setQ] = useState("");
  const [turns, setTurns] = useState<Turn[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  const spName = (id: string) => meeting.speakers.find((s) => s.id === id)?.name ?? "Unknown";
  const last = turns[turns.length - 1];
  const busy = !!last && !turnDone(last);

  function ask(question: string) {
    const query = question.trim();
    if (!query || busy) return;
    const tokens = composeAnswer(meeting, query, spName);
    const total = tokens.reduce((n, tk) => n + tokenChars(tk), 0);
    setTurns((t) => [...t, { q: query, tokens, revealed: 0, total }]);
    setQ("");
  }

  // stream the newest turn
  useEffect(() => {
    const lastTurn = turns[turns.length - 1];
    if (!lastTurn || turnDone(lastTurn)) return;
    const timer = setInterval(() => {
      setTurns((ts) => {
        const l = ts[ts.length - 1];
        if (!l || turnDone(l)) return ts;
        const revealed = Math.min(l.total, l.revealed + 3);
        return [...ts.slice(0, -1), { ...l, revealed }];
      });
    }, 16);
    return () => clearInterval(timer);
  }, [turns]);

  // keep the stream pinned to the bottom
  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight });
  }, [turns]);

  const suggestions =
    meeting.id === "q3-roadmap"
      ? ["What did we decide about pricing?", "Why is activation dropping?", "What does Maya own?"]
      : ["What did we commit to?", "Any risks mentioned?", "Who owns what?"];

  return (
    <div className={"flex h-full min-h-0 flex-col " + (className ?? "")}>
      <div ref={listRef} className="scrollpane min-h-0 flex-1 overflow-y-auto">
        {turns.length === 0 && (
          <div className="px-4 py-4">
            <p className="text-[12.5px] leading-relaxed text-ink-faint">
              Ask anything about this call in plain words. Nothing is invented — every answer is
              made of quotes you can play back.
            </p>
            <div className="mt-2.5 flex flex-wrap gap-1.5">
              {suggestions.map((s) => (
                <button
                  key={s}
                  onClick={() => ask(s)}
                  className="rounded-full border border-line bg-raised px-2.5 py-1 text-[12.5px] text-ink-soft hover:border-ink-soft hover:text-ink"
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        )}
        <ul className="space-y-4 px-4 py-4">
          {turns.map((tn, i) => (
            <li key={i}>
              <p className="mb-1 rounded-lg bg-line-soft px-3 py-1.5 text-[13.5px] leading-relaxed text-ink">
                {tn.q}
              </p>
              <AnswerStream turn={tn} onSeek={player.seek} streaming={!turnDone(tn)} />
            </li>
          ))}
        </ul>
      </div>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          ask(q);
        }}
        className="flex gap-2 border-t border-line px-3 py-3"
      >
        <input
          ref={inputRef}
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Ask this call…"
          aria-label="Ask this call"
          className="min-w-0 flex-1 rounded-full border border-line bg-paper px-4 py-2 text-[14px] focus:outline-none"
        />
        <button
          type="submit"
          disabled={busy}
          className="shrink-0 rounded-full bg-ink px-4 py-2 text-[13.5px] font-medium text-paper hover:opacity-90 disabled:opacity-50"
        >
          Ask
        </button>
      </form>
    </div>
  );
}

function turnDone(t: Turn): boolean {
  return t.revealed >= t.total;
}

/** Renders one turn's answer as it streams: text reveals left→right, citations become chips. */
function AnswerStream({
  turn,
  onSeek,
  streaming,
}: {
  turn: Turn;
  onSeek: (t: number) => void;
  streaming: boolean;
}) {
  const parts: React.ReactNode[] = [];
  let budget = turn.revealed;
  turn.tokens.forEach((tk, i) => {
    if ("cite" in tk) {
      if (budget >= tokenChars(tk)) {
        parts.push(
          <button
            key={i}
            onClick={() => onSeek(tk.cite.t)}
            aria-label={`Play from ${mmss(tk.cite.t)}`}
            className="mx-0.5 inline-block translate-y-[-1px] rounded bg-record-soft px-1 font-mono text-[11.5px] font-medium text-record tabular-nums hover:bg-record hover:text-paper"
          >
            [{mmss(tk.cite.t)}]
          </button>
        );
        budget -= tokenChars(tk);
      }
    } else {
      const shown = tk.text.slice(0, Math.max(0, budget));
      budget -= tk.text.length;
      if (shown.length === 0) return;
      parts.push(<span key={i}>{shown}</span>);
    }
  });

  return (
    <p className="mt-1 whitespace-pre-line text-[13.5px] leading-relaxed text-ink-soft">
      {parts}
      {streaming && (
        <span className="ml-0.5 inline-block h-3.5 w-1.5 animate-pulse bg-record align-text-bottom" />
      )}
    </p>
  );
}

"use client";

import type { Meeting } from "@/lib/model";
import { usePlayer } from "@/lib/player";
import { Player } from "./Player";
import { TranscriptPane } from "./TranscriptPane";
import { LeftPanel } from "./LeftPanel";
import { ChatPanel } from "./ChatPanel";
import { fmtDate, fmtTime, hms } from "@/lib/time";
import { useEffect, useState } from "react";

export function MeetingView({ meeting, initialTime }: { meeting: Meeting; initialTime: number }) {
  const player = usePlayer(meeting, initialTime);
  const [copiedLink, setCopiedLink] = useState(false);
  const [chatOpen, setChatOpen] = useState(false);

  // keyboard: space = play/pause, arrows seek, Escape closes chat (when not typing)
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") {
        if (e.key === "Escape") {
          (e.target as HTMLElement).blur();
          setChatOpen(false);
        }
        return;
      }
      if (e.code === "Space") {
        e.preventDefault();
        player.toggle();
      }
      if (e.key === "ArrowRight") player.seek(player.t + 10);
      if (e.key === "ArrowLeft") player.seek(player.t - 10);
      if (e.key === "Escape") setChatOpen(false);
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [player]);

  async function copyAtCurrentTime() {
    const url = `${window.location.origin}/m/${meeting.id}?t=${Math.floor(player.t)}`;
    try {
      await navigator.clipboard.writeText(url);
      setCopiedLink(true);
      setTimeout(() => setCopiedLink(false), 2000);
    } catch {
      setCopiedLink(false);
    }
  }

  const others = meeting.speakers.filter((s) => !s.self);

  return (
    <div className="mx-auto max-w-6xl px-4 pb-16 pt-8 sm:px-6">
      {/* ── header ─────────────────────────────────────────────────────── */}
      <div className="mb-6 flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0">
          <h1 className="font-[family-name:var(--font-display)] text-[32px] font-medium leading-tight tracking-tight">
            {meeting.title}
          </h1>
          <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[13.5px] text-ink-soft">
            <span>
              {fmtDate(meeting.startedAt)} · {fmtTime(meeting.startedAt)}
            </span>
            <span className="font-mono tabular-nums text-ink-faint">{hms(meeting.duration)}</span>
            <span>{meeting.platform}</span>
            <span
              className={
                "rounded-full px-2 py-0.5 text-[11.5px] font-medium " +
                (meeting.captureMode === "bot"
                  ? "bg-line-soft text-ink-soft"
                  : "bg-ok-soft text-ok")
              }
            >
              {meeting.captureMode === "bot" ? "bot recorded" : "bot-free capture"}
            </span>
          </div>
          <div className="mt-2 flex items-center gap-1.5 text-[13px] text-ink-soft">
            <span className="inline-flex -space-x-1.5" aria-hidden>
              {others.slice(0, 8).map((s) => (
                <span
                  key={s.id}
                  className="inline-block size-2.5 rounded-full ring-2 ring-paper"
                  style={{ background: s.color }}
                />
              ))}
            </span>
            <span>
              {others.map((s) => s.name.split(" ")[0]).join(", ")}
              {others.length === 0 ? " solo test" : ""}
            </span>
          </div>
        </div>
        <div className="flex shrink-0 gap-2">
          <button
            onClick={() => setChatOpen(true)}
            aria-expanded={chatOpen}
            className="rounded-full bg-ink px-3.5 py-2 text-[13px] font-medium text-paper hover:opacity-90"
          >
            Chat with the call
          </button>
          <button
            onClick={copyAtCurrentTime}
            className="rounded-full border border-line bg-raised px-3.5 py-2 text-[13px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink"
          >
            {copiedLink ? "Link copied" : "Copy link to this moment"}
          </button>
        </div>
      </div>

      {/* chat dock — a right sidebar that overlays the transcript while open */}
      {chatOpen && (
        <aside
          className="fixed bottom-0 right-0 top-0 z-40 flex w-[380px] max-w-[95vw] flex-col border-l border-line bg-paper shadow-[-12px_0_32px_rgba(27,30,36,0.10)]"
          aria-label="Chat with the call"
        >
          <div className="flex items-center justify-between border-b border-line px-4 pt-[70px] pb-2.5">
            <div>
              <h2 className="text-[14px] font-semibold">Chat with the call</h2>
              <p className="text-[11.5px] text-ink-faint">answers are playable quotes, nothing invented</p>
            </div>
            <button
              onClick={() => setChatOpen(false)}
              className="rounded-full border border-line bg-raised px-3 py-1 text-[12.5px] text-ink-soft hover:border-ink-soft hover:text-ink"
            >
              Close
            </button>
          </div>
          <ChatPanel meeting={meeting} player={player} className="min-h-0 flex-1" />
        </aside>
      )}

      {/* ── panes ──────────────────────────────────────────────────────── */}
      <div className="grid grid-cols-1 items-start gap-8 lg:grid-cols-[minmax(0,1fr)_400px] xl:grid-cols-[minmax(0,1fr)_440px]">
        <div className="min-w-0 space-y-6">
          <Player meeting={meeting} player={player} />
          <LeftPanel meeting={meeting} player={player} />
        </div>
