// Minutes — core data model.
// A meeting carries everything the product renders: speakers, the transcript,
// and every artifact that deep-links back to a moment (highlights, action
// items, summary sections, follow-up email draft).

export type Speaker = {
  id: string;
  name: string;
  /** hue used for the speaking graph and transcript labels */
  color: string;
  /** the signed-in user */
  self?: boolean;
};

export type Utterance = {
  /** seconds from recording start */
  t: number;
  /** seconds the utterance lasts (drives the speaking graph) */
  dur: number;
  speaker: string; // speaker id
  text: string;
};

export type Highlight = {
  id: string;
  at: number;
  title: string;
  note?: string;
  /** optional category chosen at capture time */
  tag?: "decision" | "question" | "action" | "moment" | "risk";
};

export type ActionItem = {
  id: string;
  ownerName: string;
  text: string;
  due?: string;
  cite: number; // Utterance t it was extracted from
  done?: boolean;
};

export type SummaryBullet = { text: string; cite: number };

export type Summary = {
  template: string;
  gist: string;
  sections: {
    heading: string;
    bullets: SummaryBullet[];
  }[];
};

export type Meeting = {
  id: string;
  title: string;
  platform: "Zoom" | "Google Meet" | "Microsoft Teams" | "In person";
  startedAt: string; // ISO
  duration: number; // seconds
  captureMode: "bot" | "bot-free";
  status: "recorded";
  speakers: Speaker[];
  transcript: Utterance[];
  highlights: Highlight[];
  actionItems: ActionItem[];
  summaries: Record<string, Summary>; // template id -> rendered summary
  defaultTemplate: string;
  emailDraft: string;
  /** available templates come from summaries' keys, ordered by templates order */
};

/** Events Minutes has read off the calendar but not recorded (yet). */
export type Upcoming = {
  id: string;
  title: string;
  platform: "Zoom" | "Google Meet" | "Microsoft Teams" | "In person";
  startedAt: string;
  attendees: string[]; // names (incl. self)
  captureMode: "bot" | "bot-free"; // how the notetaker will join this one
};

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { SearchForm } from "@/components/SearchForm";

export function TopBar() {
  const pathname = usePathname();
  // a shared clip page is read by someone who was never on the call —
  // no app nav, just the wordmark they'll see again if they get access
  const isShare = pathname?.startsWith("/share/");
  return (
    <header className="rule sticky top-0 z-40 bg-paper">
      <div className="mx-auto flex h-14 max-w-6xl items-center gap-6 px-4 sm:px-6">
        <Link
          href={isShare ? "#" : "/"}
          className="flex items-baseline gap-1 text-xl leading-none"
          aria-label={isShare ? "Minutes" : "Minutes home"}
        >
          <span
            className="font-[family-name:var(--font-display)] font-semibold tracking-tight"
            style={{ fontOpticalSizing: "auto" }}
          >
            Minutes
          </span>
          <span aria-hidden className="rec-dot size-1.5 translate-y-[-2px] rounded-full bg-record" />
        </Link>
        {!isShare && (
          <nav className="ml-auto flex items-center gap-5 text-sm">
            <Link href="/" className="text-ink-soft hover:text-ink">
              Meetings
            </Link>
            <Link
              href="/search"
              className="hidden text-ink-soft hover:text-ink sm:block"
            >
              Search
            </Link>
            <SearchForm />
            <Link
              href="/settings"
              className="text-ink-soft hover:text-ink"
              aria-label="Settings"
            >
              Settings
            </Link>
          </nav>
        )}
      </div>
    </header>
  );
}

