1	import type { Utterance } from "@/lib/model";
2	
3	// Transcripts are authored with a builder so timestamps stay consistent with
4	// a natural speaking cadence (~2.6 words/sec) instead of hand-counted.
5	export function builder() {
6	  let t = 0;
7	  const lines: Utterance[] = [];
8	  return {
9	    say(speaker: string, text: string) {
10	      const words = text.split(/\s+/).length;
11	      const dur = Math.max(1.8, Math.round((words / 2.6) * 10) / 10);
12	      lines.push({ t: Math.round(t), dur, speaker, text });
13	      t += dur + 0.9;
14	    },
15	    /** silence: screen-share stretch, pause, or side conversation */
16	    gap(sec: number) {
17	      t += sec;
18	    },
19	    get end() {
20	      return Math.round(t);
21	    },
22	    built: () => lines,
23	  };
24	}
25	
26	export function mmss(sec: number): string {
27	  const h = Math.floor(sec / 3600);
28	  const m = Math.floor((sec % 3600) / 60);
29	  const s = Math.floor(sec % 60);
30	  const mm = h > 0 ? String(m).padStart(2, "0") : String(m);
31	  return `${h > 0 ? h + ":" : ""}${mm}:${String(s).padStart(2, "0")}`;
32	}

